// An invented server library. Its reply object carries body sends (`json`,
// `send`, `end`, `write`) beside setters (`status`, `header`, `cookie`) that
// return the reply too, so the reply type alone does not tell them apart.
export interface Reply {
  statusCode: number;
  setHeader(name: string, value: string): Reply;
  getHeader(name: string): string | undefined;
  status(code: number): Reply;
  json(body: unknown): Reply;
  send(body?: unknown): Reply;
  end(body?: unknown): Reply;
  write(chunk: unknown): boolean;
  header(name: string, value: string): Reply;
  cookie(name: string, value: unknown): Reply;
}
export interface Request {
  body: unknown;
}
export type Handler = (req: Request, res: Reply) => void | Promise<void>;
export interface App {
  get(path: string, handler: Handler): App;
  post(path: string, handler: Handler): App;
}
declare function make(): App;
export default make;
export declare const reply: Reply;
